/* Word of the day and quote of the day. */
window.MV = window.MV || {};
MV.DAILY = {
  words: [
    { w: "candid", pos: "adjective", say: "KAN-did", meaning: "Honest and direct, even when the truth is not pleasant.", example: "She gave me candid feedback on my presentation.", tip: "Use it when someone speaks openly: “To be candid, I disagree.”" },
    { w: "nuance", pos: "noun", say: "NYOO-ahns", meaning: "A small difference in meaning, tone or feeling that is easy to miss.", example: "A good translator catches every nuance of the Marathi original.", tip: "Often used as “nuanced” (adjective): “a nuanced view” means a view that sees more than black and white." },
    { w: "pragmatic", pos: "adjective", say: "prag-MAT-ik", meaning: "Dealing with a problem in a practical way that works, not in a perfect way.", example: "Hiring a tempo for one day was the pragmatic way to shift the office.", tip: "Close to “practical”, but “pragmatic” is more about choices and decisions: “a pragmatic approach”." },
    { w: "resilient", pos: "adjective", say: "ri-ZIL-ee-uhnt", meaning: "Able to recover quickly after a difficulty or a setback.", example: "Mumbai is a resilient city; the trains were running again the morning after the floods.", tip: "The noun is “resilience”. Use it for people, teams, businesses and even materials." },
    { w: "articulate", pos: "adjective", say: "ar-TIK-yuh-luht", meaning: "Able to express thoughts clearly in words.", example: "The new manager is articulate and explains each decision in simple words.", tip: "It is also a verb, said ar-TIK-yuh-layt: “He could not articulate what was worrying him.”" },
    { w: "ambiguous", pos: "adjective", say: "am-BIG-yoo-uhs", meaning: "Having more than one possible meaning, so it is not clear.", example: "The email was ambiguous, so half the team came on Friday and half on Saturday.", tip: "The noun is “ambiguity”. To fix an ambiguous sentence, add the missing detail: who, what, when." },
    { w: "concise", pos: "adjective", say: "kuhn-SYSE", meaning: "Giving the needed information in few words.", example: "Keep your update concise; the director has only five minutes.", tip: "Concise does not mean incomplete. It means nothing extra. The opposite is “wordy” or “long-winded”." },
    { w: "diligent", pos: "adjective", say: "DIL-i-juhnt", meaning: "Working carefully and steadily, without giving up.", example: "Our accountant is diligent; she checks every GST entry twice.", tip: "The noun is “diligence”. In business, “due diligence” means checking the facts carefully before a deal." },
    { w: "empathy", pos: "noun", say: "EM-puh-thee", meaning: "The ability to understand and share how another person feels.", example: "The nurse spoke to my mother with real empathy.", tip: "Do not mix it up with “sympathy”. Sympathy is feeling sorry for someone; empathy is feeling with them." },
    { w: "bias", pos: "noun", say: "BY-uhs", meaning: "A leaning for or against something that stops you from judging fairly.", example: "The interview panel used a common score sheet to reduce bias.", tip: "The adjective is “biased”: say “He is biased”, not “He is bias”." },
    { w: "leverage", pos: "verb", say: "LEE-vuh-rij", meaning: "To use something you already have to get a better result.", example: "We can leverage our old customer list to launch the new product.", tip: "Also a noun: “Our large order gave us leverage in the price talks.” In plain talk, “use” is often enough." },
    { w: "prioritise", pos: "verb", say: "pry-OR-i-tyze", meaning: "To decide what is most important and do it first.", example: "With the audit next week, we must prioritise the pending invoices.", tip: "British and Indian spelling uses “-ise”; American spelling is “prioritize”. The noun is “priority”." },
    { w: "tangible", pos: "adjective", say: "TAN-juh-buhl", meaning: "Real and clear enough to be seen, touched or measured.", example: "The training gave tangible results: complaints fell by half in three months.", tip: "The opposite is “intangible”, for things like goodwill or brand value that you cannot touch." },
    { w: "inevitable", pos: "adjective", say: "in-EV-i-tuh-buhl", meaning: "Certain to happen; impossible to avoid.", example: "With so many new flats in the area, more traffic was inevitable.", tip: "Common phrase: “It was inevitable that…”. The adverb is “inevitably”." },
    { w: "plausible", pos: "adjective", say: "PLAW-zuh-buhl", meaning: "Reasonable and likely to be true, though not yet proved.", example: "His reason for the delay sounded plausible, so I did not question it.", tip: "Plausible means “could be true”, not “is true”. The opposite is “implausible”." },
    { w: "scrutiny", pos: "noun", say: "SKROO-ti-nee", meaning: "Very careful and close examination.", example: "Every expense claim above ten thousand rupees comes under scrutiny.", tip: "Common phrases: “under scrutiny”, “close scrutiny”. The verb is “scrutinise”." },
    { w: "tentative", pos: "adjective", say: "TEN-tuh-tiv", meaning: "Not yet fixed or certain; likely to change.", example: "We have a tentative date for the wedding, but the hall is not booked yet.", tip: "Useful in planning: “a tentative schedule”, “tentatively on the 14th”." },
    { w: "versatile", pos: "adjective", say: "VUR-suh-tyle", meaning: "Able to do many different things well.", example: "She is a versatile employee who handles sales, billing and customer calls.", tip: "Use it for people, tools and even food: “Paneer is a versatile ingredient.”" },
    { w: "coherent", pos: "adjective", say: "koh-HEER-uhnt", meaning: "Clear and logical, with all parts fitting together well.", example: "His report was coherent: problem, cause, solution, cost.", tip: "The opposite is “incoherent”, used for speech or writing that is confused and hard to follow." },
    { w: "compelling", pos: "adjective", say: "kuhm-PEL-ing", meaning: "So strong or interesting that it holds your attention or convinces you.", example: "She made a compelling case for opening a branch in Pune.", tip: "Common pairs: “a compelling reason”, “a compelling argument”, “a compelling story”." },
    { w: "credible", pos: "adjective", say: "KRED-uh-buhl", meaning: "Able to be believed or trusted.", example: "Check that the news comes from a credible source before you forward it on WhatsApp.", tip: "Do not confuse it with “creditable”, which means deserving praise. The noun is “credibility”." },
    { w: "deliberate", pos: "adjective", say: "di-LIB-uh-ruht", meaning: "Done on purpose, or done slowly and carefully.", example: "Leaving her name off the list was a mistake, not a deliberate act.", tip: "As a verb it is said di-LIB-uh-rayt and means to think carefully: “The committee deliberated for two hours.”" },
    { w: "feasible", pos: "adjective", say: "FEE-zuh-buhl", meaning: "Possible to do with the time, money and people you have.", example: "It is not feasible to finish the interior work before Diwali.", tip: "Feasible is about “can it be done?”, not “should it be done?”. The noun is “feasibility”." },
    { w: "implicit", pos: "adjective", say: "im-PLIS-it", meaning: "Understood without being said directly.", example: "There was an implicit understanding that the eldest son would run the shop.", tip: "The opposite is “explicit”. Remember: implicit is hinted, explicit is spelled out." },
    { w: "meticulous", pos: "adjective", say: "muh-TIK-yuh-luhs", meaning: "Very careful about every small detail.", example: "My father keeps meticulous records of every household bill.", tip: "It is a compliment. Common phrases: “meticulous planning”, “meticulous about hygiene”." },
    { w: "objective", pos: "adjective", say: "uhb-JEK-tiv", meaning: "Based on facts, not on personal feelings or opinions.", example: "Ask someone outside the family for an objective opinion on the property price.", tip: "The opposite is “subjective”. As a noun, “objective” means a goal: “our main objective this year”." },
    { w: "redundant", pos: "adjective", say: "ri-DUN-duhnt", meaning: "Not needed, because something else already does the same job.", example: "“Return back” is redundant; “return” already means to come back.", tip: "Common Indian English redundancies to avoid: “revert back”, “repeat again”, “discuss about”." },
    { w: "substantial", pos: "adjective", say: "suhb-STAN-shuhl", meaning: "Large in amount, size or importance.", example: "They made a substantial saving by buying the school books second-hand.", tip: "More formal than “big”. Good in reports: “a substantial increase”, “substantial progress”." },
    { w: "subtle", pos: "adjective", say: "SUT-uhl", meaning: "Not obvious; small or delicate and so hard to notice.", example: "There is a subtle difference in taste between the two brands of tea.", tip: "The “b” is silent. The noun is “subtlety” and the adverb is “subtly”." },
    { w: "trivial", pos: "adjective", say: "TRIV-ee-uhl", meaning: "Small and not important.", example: "Do not waste the meeting on trivial matters like the colour of the folder.", tip: "The opposite is “significant” or “serious”. The verb “trivialise” means to make something seem less important than it is." },
    { w: "sceptical", pos: "adjective", say: "SKEP-ti-kuhl", meaning: "Having doubts; not ready to believe something easily.", example: "I am sceptical of any scheme that promises to double my money in a year.", tip: "British and Indian spelling is “sceptical”; American is “skeptical”. Say “sceptical of” or “sceptical about”." },
    { w: "consensus", pos: "noun", say: "kuhn-SEN-suhs", meaning: "An agreement that most people in a group accept.", example: "The housing society reached a consensus on the new parking rules.", tip: "Say “reach a consensus” or “build consensus”. Avoid “general consensus”, which is redundant." },
    { w: "dilemma", pos: "noun", say: "di-LEM-uh", meaning: "A situation where you must choose between two difficult options.", example: "He faced a dilemma: take the better job in Bengaluru or stay near his parents.", tip: "Use it only when both choices are hard. A simple problem is not a dilemma." },
    { w: "paradox", pos: "noun", say: "PAR-uh-doks", meaning: "A statement or situation that seems to go against itself but may still be true.", example: "It is a paradox that the more choices we have online, the harder it is to decide.", tip: "The adjective is “paradoxical”. A classic example: “Less is more.”" },
    { w: "rationale", pos: "noun", say: "rash-uh-NAHL", meaning: "The reasons that explain a decision or a plan.", example: "Please explain the rationale behind the new leave policy.", tip: "Do not confuse it with “rational” (adjective, meaning sensible). “Rationale” is a noun: “the rationale for…”." },
    { w: "hindsight", pos: "noun", say: "HYND-syte", meaning: "Understanding of an event that comes only after it has happened.", example: "In hindsight, we should have bought the flat before prices went up.", tip: "Almost always used as “in hindsight” or “with hindsight”. The opposite idea is “foresight”." },
    { w: "momentum", pos: "noun", say: "moh-MEN-tuhm", meaning: "The force that keeps something moving or growing once it has started.", example: "The savings habit gained momentum once she set up a monthly SIP.", tip: "Common verbs: “gain”, “build”, “lose” and “keep up” momentum." },
    { w: "benchmark", pos: "noun", say: "BENCH-mark", meaning: "A standard used to compare and judge other things.", example: "The Nifty 50 is the benchmark that many mutual funds try to beat.", tip: "Also a verb: “We benchmark our prices against three competitors.”" },
    { w: "trade-off", pos: "noun", say: "TRAYD-off", meaning: "A balance where you give up one good thing to get another.", example: "Living far from the office is a trade-off: lower rent but a longer commute.", tip: "Say “a trade-off between cost and quality”. It reminds listeners that every choice has a price." },
    { w: "bottleneck", pos: "noun", say: "BOT-uhl-nek", meaning: "The one slow point that holds up the whole process.", example: "Approvals from head office are the bottleneck in our hiring.", tip: "Think of the narrow neck of a bottle. Fixing the bottleneck speeds up everything else." },
    { w: "incentive", pos: "noun", say: "in-SEN-tiv", meaning: "Something that encourages a person to act in a certain way.", example: "The company offers a cash incentive to staff who meet the quarterly target.", tip: "Say “an incentive to do something” or “an incentive for someone”. The opposite is “disincentive”." },
    { w: "mitigate", pos: "verb", say: "MIT-i-gayt", meaning: "To make something bad less serious or less harmful.", example: "A health insurance policy mitigates the risk of a large hospital bill.", tip: "You mitigate a risk, a loss or damage. Do not write “mitigate against”; that mixes it up with “militate against”." },
    { w: "allocate", pos: "verb", say: "AL-uh-kayt", meaning: "To give out money, time or resources for a particular purpose.", example: "We allocate part of every salary to the children’s education fund.", tip: "Say “allocate something to” or “allocate something for”. The noun is “allocation”." },
    { w: "anticipate", pos: "verb", say: "an-TIS-i-payt", meaning: "To expect something and prepare for it in advance.", example: "We anticipated heavy rain and moved the function indoors.", tip: "Stronger than “expect”: it includes getting ready. The noun is “anticipation”." },
    { w: "clarify", pos: "verb", say: "KLAR-i-fy", meaning: "To make something clear and easier to understand.", example: "Could you clarify whether the fee includes GST?", tip: "A polite way to ask a question in a meeting: “May I clarify one point?” The noun is “clarification”." },
    { w: "delegate", pos: "verb", say: "DEL-i-gayt", meaning: "To give part of your work or power to someone else.", example: "A good manager delegates routine tasks and keeps time for planning.", tip: "As a noun it is said DEL-i-guht and means a person sent to represent others, as at a conference." },
    { w: "elaborate", pos: "verb", say: "i-LAB-uh-rayt", meaning: "To explain something in more detail.", example: "Could you elaborate on the second point in your proposal?", tip: "Say “elaborate on”. As an adjective it is said i-LAB-uh-ruht and means detailed and carefully made: “an elaborate rangoli”." },
    { w: "reconcile", pos: "verb", say: "REK-uhn-syle", meaning: "To make two things agree, or to bring people back to friendly terms.", example: "At month end we reconcile the cash book with the bank statement.", tip: "For people: “The brothers were reconciled after years.” The noun is “reconciliation”." },
    { w: "undermine", pos: "verb", say: "un-der-MYNE", meaning: "To slowly make something weaker or less effective.", example: "Correcting a team member in front of the client can undermine her confidence.", tip: "You undermine trust, authority, confidence or an effort. It usually happens quietly, bit by bit." },
    { w: "advocate", pos: "verb", say: "AD-vuh-kayt", meaning: "To support an idea or a plan in public.", example: "Our doctor advocates a daily walk of thirty minutes.", tip: "Say “advocate something”, not “advocate for something”, in formal British usage. The noun is said AD-vuh-kuht; in India it also means a lawyer." },
    { w: "accountable", pos: "adjective", say: "uh-KOWN-tuh-buhl", meaning: "Responsible for your actions and expected to explain them.", example: "The site engineer is accountable for safety on the construction site.", tip: "Say “accountable for a result” and “accountable to a person”. The noun is “accountability”." },
    { w: "adapt", pos: "verb", say: "uh-DAPT", meaning: "To change so that you fit a new situation.", example: "Small shopkeepers adapted quickly to UPI payments.", tip: "Do not confuse it with “adopt” (to take up as your own). You adapt to change; you adopt a new method." },
    { w: "assess", pos: "verb", say: "uh-SES", meaning: "To judge the quality, value or size of something after thinking carefully.", example: "The bank will assess your income before approving the home loan.", tip: "More careful than “check”. The noun is “assessment”: “a fair assessment of the risks”." },
    { w: "assumption", pos: "noun", say: "uh-SUMP-shuhn", meaning: "Something you take to be true without having proof.", example: "The budget rests on the assumption that sales will grow by ten per cent.", tip: "Say “make an assumption” or “on the assumption that”. Good practice: state your assumptions at the start." },
    { w: "authentic", pos: "adjective", say: "aw-THEN-tik", meaning: "Real and true; not a copy or a fake.", example: "This small restaurant in Dadar serves authentic Malvani food.", tip: "Used for objects, food, documents and people. An authentic person does not pretend to be someone else." },
    { w: "collaborate", pos: "verb", say: "kuh-LAB-uh-rayt", meaning: "To work together with others to produce or achieve something.", example: "The design and sales teams collaborated on the new brochure.", tip: "Say “collaborate with someone on something”. The noun is “collaboration”." },
    { w: "compromise", pos: "noun", say: "KOM-pruh-myze", meaning: "An agreement where each side gives up a little of what it wanted.", example: "After a long talk, the two brothers reached a compromise over the family land.", tip: "As a verb it can also mean to weaken or put at risk: “Never compromise on safety.”" },
    { w: "comprehensive", pos: "adjective", say: "kom-pri-HEN-siv", meaning: "Complete; including everything that is needed.", example: "Take a comprehensive insurance policy for the new car, not just third-party cover.", tip: "Do not confuse it with “comprehensible”, which means easy to understand." },
    { w: "consistent", pos: "adjective", say: "kuhn-SIS-tuhnt", meaning: "Always behaving or performing in the same way.", example: "Rahul Dravid was known as a consistent batsman, not a flashy one.", tip: "Say “consistent with” when two things agree: “The result is consistent with our forecast.” The noun is “consistency”." },
    { w: "constraint", pos: "noun", say: "kuhn-STRAYNT", meaning: "A limit that controls what you can do.", example: "Because of budget constraints, we will hire two people instead of four.", tip: "Common pairs: “time constraints”, “budget constraints”. The verb is “constrain”." },
    { w: "context", pos: "noun", say: "KON-tekst", meaning: "The situation or background that helps you understand something.", example: "Without context, his short reply sounded rude, but he was only in a hurry.", tip: "Common phrases: “in this context”, “out of context”, “to give some context”." },
    { w: "crucial", pos: "adjective", say: "KROO-shuhl", meaning: "Extremely important, because other things depend on it.", example: "The first ten overs are crucial in a run chase.", tip: "Say “crucial to” or “crucial for”. Already strong, so avoid “very crucial”." },
    { w: "discreet", pos: "adjective", say: "dis-KREET", meaning: "Careful in what you say or do, so as not to embarrass anyone or reveal a secret.", example: "Please be discreet about her salary; she told you in confidence.", tip: "Do not confuse it with “discrete”, which means separate and distinct. The noun is “discretion”." },
    { w: "diverse", pos: "adjective", say: "dy-VURS", meaning: "Made up of many different kinds of people or things.", example: "Our team is diverse, with members from six states speaking nine languages.", tip: "The noun is “diversity” and the verb is “diversify”: “Diversify your investments.”" },
    { w: "emphasise", pos: "verb", say: "EM-fuh-syze", meaning: "To give special importance or attention to something.", example: "The principal emphasised the need for regular attendance.", tip: "Say “emphasise something”, never “emphasise on something”. But the noun takes “on”: “put emphasis on”." },
    { w: "endorse", pos: "verb", say: "in-DORS", meaning: "To say publicly that you support or approve of something.", example: "The board endorsed the plan to open two new branches.", tip: "Also used for celebrities who advertise products, and for signing the back of a cheque." },
    { w: "explicit", pos: "adjective", say: "ik-SPLIS-it", meaning: "Stated clearly and fully, leaving no doubt.", example: "Give the painter explicit instructions about which walls to paint.", tip: "The opposite is “implicit”. In writing, being explicit about dates, amounts and names prevents confusion." },
    { w: "facilitate", pos: "verb", say: "fuh-SIL-i-tayt", meaning: "To make an action or a process easier.", example: "The new online portal facilitates quick payment of property tax.", tip: "You facilitate a process, not a person. Say “This will facilitate the work”, not “This will facilitate you”." },
    { w: "integrity", pos: "noun", say: "in-TEG-ri-tee", meaning: "The quality of being honest and having strong moral principles.", example: "People trusted the old cashier because of his integrity.", tip: "Say “a person of integrity”. It means doing the right thing even when no one is watching." },
    { w: "initiative", pos: "noun", say: "i-NISH-uh-tiv", meaning: "The ability to act and decide on your own, without waiting to be told.", example: "She took the initiative and called the customer before he could complain.", tip: "Say “take the initiative” or “show initiative”. It can also mean a new plan: “a government initiative”." },
    { w: "insight", pos: "noun", say: "IN-syte", meaning: "A clear and deep understanding of a person or a situation.", example: "The customer survey gave us useful insights into why people prefer smaller packs.", tip: "Say “insight into something”. The adjective is “insightful”: “an insightful comment”." },
    { w: "justify", pos: "verb", say: "JUS-ti-fy", meaning: "To show or prove that something is right or reasonable.", example: "Can we justify the cost of a second delivery van?", tip: "The noun is “justification”. “Justified” means there was a good reason: “Her anger was justified.”" },
    { w: "legitimate", pos: "adjective", say: "li-JIT-i-muht", meaning: "Fair, reasonable or allowed by law.", example: "The tenant has a legitimate complaint about the leaking roof.", tip: "Common pairs: “a legitimate concern”, “a legitimate business”, “a legitimate question”." },
    { w: "negotiate", pos: "verb", say: "ni-GOH-shee-ayt", meaning: "To discuss something in order to reach an agreement.", example: "We negotiated with the landlord and got the rent reduced by two thousand rupees.", tip: "Say “negotiate with someone for or over something”. The noun is “negotiation”." },
    { w: "perspective", pos: "noun", say: "per-SPEK-tiv", meaning: "A particular way of looking at or thinking about something.", example: "Try to see the delay from the customer’s perspective.", tip: "Do not confuse it with “prospective”, which means likely or expected in future, as in “a prospective buyer”." },
    { w: "persuade", pos: "verb", say: "per-SWAYD", meaning: "To make someone agree to do or believe something by giving good reasons.", example: "I persuaded my father to try online banking.", tip: "Say “persuade someone to do something”. The adjective is “persuasive” and the noun is “persuasion”." },
    { w: "precise", pos: "adjective", say: "pri-SYSE", meaning: "Exact and accurate in every detail.", example: "Please give me the precise amount, not a rough figure.", tip: "The noun is “precision”. Useful phrase: “to be precise”, used when you correct or sharpen what you just said." },
    { w: "proactive", pos: "adjective", say: "proh-AK-tiv", meaning: "Acting early to prevent a problem, instead of waiting for it to happen.", example: "Be proactive and renew the car insurance before it expires.", tip: "The opposite is “reactive”, which means acting only after something goes wrong." },
    { w: "relevant", pos: "adjective", say: "REL-uh-vuhnt", meaning: "Closely connected with the subject you are dealing with.", example: "Attach only the relevant documents: PAN, Aadhaar and the last three salary slips.", tip: "Say “relevant to”. The opposite is “irrelevant”. Watch the spelling: it is not “revelant”." },
    { w: "reluctant", pos: "adjective", say: "ri-LUK-tuhnt", meaning: "Not willing to do something, and so slow to do it.", example: "He was reluctant to ask his boss for leave during the busy season.", tip: "Say “reluctant to do something”. The noun is “reluctance” and the adverb is “reluctantly”." },
    { w: "rigorous", pos: "adjective", say: "RIG-uh-ruhs", meaning: "Very thorough, strict and careful.", example: "Every batch of medicine goes through rigorous testing before it leaves the factory.", tip: "The noun is “rigour” in British and Indian spelling. Common pairs: “rigorous training”, “rigorous checks”." },
    { w: "speculate", pos: "verb", say: "SPEK-yuh-layt", meaning: "To guess about something without knowing all the facts.", example: "Let us not speculate about the reason for his resignation until he tells us.", tip: "In money matters it means buying in the hope of a quick profit, which is riskier than investing." },
    { w: "streamline", pos: "verb", say: "STREEM-lyne", meaning: "To make a process simpler and faster by removing unnecessary steps.", example: "The clinic streamlined its billing, so patients no longer wait in two queues.", tip: "You streamline a process, a system or operations. Think of removing every step that adds no value." },
    { w: "sustainable", pos: "adjective", say: "suh-STAY-nuh-buhl", meaning: "Able to continue for a long time without causing harm or running out.", example: "Working fourteen hours a day is not sustainable; you will fall ill.", tip: "Used for the environment and also for habits, growth and business: “a sustainable pace”." },
    { w: "transparent", pos: "adjective", say: "trans-PAIR-uhnt", meaning: "Open and honest, with nothing hidden.", example: "The society keeps its accounts transparent and shares them at every annual meeting.", tip: "The basic meaning is “see-through”, like glass. The noun is “transparency”." },
    { w: "viable", pos: "adjective", say: "VY-uh-buhl", meaning: "Able to work successfully.", example: "A second shop is viable only if the rent stays below fifty thousand a month.", tip: "Often used for plans and businesses: “a viable option”, “commercially viable”. The noun is “viability”." },
    { w: "vulnerable", pos: "adjective", say: "VUL-nuh-ruh-buhl", meaning: "Easily hurt, harmed or attacked.", example: "Elderly people are especially vulnerable to phone and OTP fraud.", tip: "Say “vulnerable to something”. Pronounce the first “l”: VUL-nuh-ruh-buhl, not “vun-rable”." },
    { w: "composure", pos: "noun", say: "kuhm-POH-zher", meaning: "The state of being calm and in control of your feelings.", example: "She kept her composure even when the customer started shouting.", tip: "Common verbs: “keep”, “lose” and “regain” your composure. The adjective is “composed”." },
    { w: "complacent", pos: "adjective", say: "kuhm-PLAY-suhnt", meaning: "So satisfied with yourself that you stop trying or stop being careful.", example: "After two good quarters the sales team became complacent and missed the next target.", tip: "It is a criticism, not praise. Do not confuse it with “complaisant”, which means eager to please." },
    { w: "contingency", pos: "noun", say: "kuhn-TIN-juhn-see", meaning: "Something that might happen in the future, which you plan for just in case.", example: "Keep six months of expenses aside as a contingency fund.", tip: "Common phrases: “contingency plan”, “contingency fund”. It is your Plan B for when things go wrong." }
  ],
  quotes: [
    { q: "We simply attempt to be fearful when others are greedy and to be greedy only when others are fearful.", by: "Warren Buffett", who: "American investor, head of Berkshire Hathaway", means: "Be careful when everyone is excited about buying, and be brave when everyone is afraid.", src: "Berkshire Hathaway letter to shareholders, 1986" },
    { q: "It’s far better to buy a wonderful company at a fair price than a fair company at a wonderful price.", by: "Warren Buffett", who: "American investor, head of Berkshire Hathaway", means: "Quality matters more than a cheap price; a great business is worth paying a fair amount for.", src: "Berkshire Hathaway letter to shareholders, 1989" },
    { q: "When a management with a reputation for brilliance tackles a business with a reputation for bad economics, it is the reputation of the business that remains intact.", by: "Warren Buffett", who: "American investor, head of Berkshire Hathaway", means: "Even very clever managers usually cannot rescue a basically bad business.", src: "Berkshire Hathaway letter to shareholders, 1989" },
    { q: "In the business world, unfortunately, the rear-view mirror is always clearer than the windshield.", by: "Warren Buffett", who: "American investor, head of Berkshire Hathaway", means: "It is easy to understand the past, but hard to see what is coming.", src: "Berkshire Hathaway letter to shareholders, 1991" },
    { q: "The stock market serves as a relocation center at which money is moved from the active to the patient.", by: "Warren Buffett", who: "American investor, head of Berkshire Hathaway", means: "People who trade too often tend to lose money to people who wait calmly.", src: "Berkshire Hathaway letter to shareholders, 1991" },
    { q: "You only find out who is swimming naked when the tide goes out.", by: "Warren Buffett", who: "American investor, head of Berkshire Hathaway", means: "Hidden risks and weaknesses show up only when hard times come.", src: "Berkshire Hathaway letter to shareholders, 2001" },
    { q: "When we own portions of outstanding businesses with outstanding managements, our favorite holding period is forever.", by: "Warren Buffett", who: "American investor, head of Berkshire Hathaway", means: "If you own a share of a truly great business, the best plan is to keep it for a very long time.", src: "Berkshire Hathaway letter to shareholders, 1988" },
    { q: "Predicting rain doesn’t count; building arks does.", by: "Warren Buffett", who: "American investor, head of Berkshire Hathaway", means: "Seeing a problem coming is useless unless you also prepare for it.", src: "Berkshire Hathaway letter to shareholders, 2001 (he calls it “the Noah rule”)" },
    { q: "Lose money for the firm, and I will be understanding. Lose a shred of reputation for the firm, and I will be ruthless.", by: "Warren Buffett", who: "American investor, head of Berkshire Hathaway", means: "A money loss can be forgiven, but harming the company’s good name cannot.", src: "Testimony to the US Congress on Salomon Brothers, 1991" },
    { q: "Should you find yourself in a chronically-leaking boat, energy devoted to changing vessels is likely to be more productive than energy devoted to patching leaks.", by: "Warren Buffett", who: "American investor, head of Berkshire Hathaway", means: "If something keeps failing, it is often wiser to leave it than to keep repairing it.", src: "Berkshire Hathaway letter to shareholders, 1985" },
    { q: "It is remarkable how much long-term advantage people like us have gotten by trying to be consistently not stupid, instead of trying to be very intelligent.", by: "Charlie Munger", who: "American investor, Buffett’s business partner", means: "Avoiding silly mistakes again and again brings more success than trying to be brilliant.", src: "Wesco Financial annual letter for 1989; also in Poor Charlie’s Almanack" },
    { q: "I think I’ve been in the top 5% of my age cohort all my life in understanding the power of incentives, and all my life I’ve underestimated it.", by: "Charlie Munger", who: "American investor, Buffett’s business partner", means: "Rewards shape how people behave far more strongly than we expect.", src: "Speech “The Psychology of Human Misjudgment”, Harvard, 1995" },
    { q: "The safest way to try to get what you want is to try to deserve what you want.", by: "Charlie Munger", who: "American investor, Buffett’s business partner", means: "The surest path to success is to truly earn it.", src: "USC Law School commencement address, 2007" },
    { q: "Wisdom acquisition is a moral duty.", by: "Charlie Munger", who: "American investor, Buffett’s business partner", means: "Becoming wiser is not just useful; it is something we owe to ourselves and to others.", src: "USC Law School commencement address, 2007" },
    { q: "I’m not entitled to have an opinion on this subject unless I can state the arguments against my position better than the people do who are supporting it.", by: "Charlie Munger", who: "American investor, Buffett’s business partner", means: "Before holding a strong opinion, understand the other side’s case as well as they do.", src: "USC Law School commencement address, 2007" },
    { q: "I constantly see people rise in life who are not the smartest, sometimes not even the most diligent, but they are learning machines.", by: "Charlie Munger", who: "American investor, Buffett’s business partner", means: "People who keep learning every day often get ahead of people who are simply clever.", src: "USC Law School commencement address, 2007" },
    { q: "In my whole life, I have known no wise people (over a broad subject matter area) who didn’t read all the time, none, zero.", by: "Charlie Munger", who: "American investor, Buffett’s business partner", means: "Every truly wise person he has met is a constant reader.", src: "Poor Charlie’s Almanack" },
    { q: "Spend each day trying to be a little wiser than you were when you woke up.", by: "Charlie Munger", who: "American investor, Buffett’s business partner", means: "Aim to learn a little every single day; small gains add up over a lifetime.", src: "Poor Charlie’s Almanack" },
    { q: "All I want to know is where I’m going to die, so I’ll never go there.", by: "Charlie Munger", who: "American investor, Buffett’s business partner", means: "A good way to do well in life is to find out what causes failure and stay away from it.", src: "Poor Charlie’s Almanack (a joke he often retold to explain thinking backwards)" },
    { q: "Generally speaking, envy, resentment, revenge, and self-pity are disastrous modes of thought.", by: "Charlie Munger", who: "American investor, Buffett’s business partner", means: "Jealousy, grudges and feeling sorry for yourself only harm your own thinking.", src: "USC Law School commencement address, 2007" },
    { q: "The weak can never forgive. Forgiveness is the attribute of the strong.", by: "Mahatma Gandhi", who: "leader of India’s freedom struggle", means: "It takes real inner strength to forgive someone.", src: "Young India, 2 April 1931" },
    { q: "Strength does not come from physical capacity. It comes from an indomitable will.", by: "Mahatma Gandhi", who: "leader of India’s freedom struggle", means: "True strength is a mind that refuses to give up, not a powerful body.", src: "“The Doctrine of the Sword”, Young India, 11 August 1920" },
    { q: "Freedom is not worth having if it does not connote freedom to err and even to sin.", by: "Mahatma Gandhi", who: "leader of India’s freedom struggle", means: "Real freedom must include the freedom to make mistakes.", src: "Young India, 12 March 1931" },
    { q: "Non-violence is the greatest force at the disposal of mankind. It is mightier than the mightiest weapon of destruction devised by the ingenuity of man.", by: "Mahatma Gandhi", who: "leader of India’s freedom struggle", means: "Peaceful action is more powerful than any weapon people have invented.", src: "Harijan, 20 July 1935" },
    { q: "Arise, awake, and stop not till the goal is reached.", by: "Swami Vivekananda", who: "Indian monk and teacher", means: "Get up, get going, and do not stop until you have achieved your aim.", src: "From his lectures in India, 1897; adapted from the Katha Upanishad" },
    { q: "Take up one idea. Make that one idea your life: think of it, dream of it, live on that idea.", by: "Swami Vivekananda", who: "Indian monk and teacher", means: "Great results come from giving your full attention to one goal.", src: "Raja Yoga (1896), chapter on Pratyahara and Dharana" },
    { q: "They alone live who live for others; the rest are more dead than alive.", by: "Swami Vivekananda", who: "Indian monk and teacher", means: "A life has real meaning only when it is spent helping other people.", src: "Letter, 1894; Complete Works, Volume 4" },
    { q: "We are what our thoughts have made us; so take care of what you think.", by: "Swami Vivekananda", who: "Indian monk and teacher", means: "Your thoughts shape the person you become, so choose them with care.", src: "Inspired Talks (1895); Complete Works, Volume 7" },
    { q: "Where the mind is without fear and the head is held high; where knowledge is free.", by: "Rabindranath Tagore", who: "Indian poet and Nobel laureate", means: "He dreams of a country where people live with dignity, without fear, and where everyone can learn.", src: "Gitanjali (1912), poem 35" },
    { q: "A mind all logic is like a knife all blade. It makes the hand bleed that uses it.", by: "Rabindranath Tagore", who: "Indian poet and Nobel laureate", means: "Reason without feeling can hurt the very person who relies on it.", src: "Stray Birds (1916), verse 193" },
    { q: "If you shed tears when you miss the sun, you also miss the stars.", by: "Rabindranath Tagore", who: "Indian poet and Nobel laureate", means: "If you keep crying over what you lost, you will fail to see the good that is still there.", src: "Stray Birds (1916), verse 6" },
    { q: "The butterfly counts not months but moments, and has time enough.", by: "Rabindranath Tagore", who: "Indian poet and Nobel laureate", means: "A life feels full when you enjoy each moment, however short it is.", src: "Fireflies (1928)" },
    { q: "Let me not pray to be sheltered from dangers but to be fearless in facing them.", by: "Rabindranath Tagore", who: "Indian poet and Nobel laureate", means: "Ask for courage to face trouble, not for a life without trouble.", src: "Fruit-Gathering (1916), poem 79" },
    { q: "I measure the progress of a community by the degree of progress which women have achieved.", by: "Dr B. R. Ambedkar", who: "chief architect of India’s Constitution", means: "A society has moved forward only as far as its women have moved forward.", src: "Speech to the All-India Depressed Classes Women’s Conference, Nagpur, 20 July 1942" },
    { q: "Man needs his difficulties because they are necessary to enjoy success.", by: "A. P. J. Abdul Kalam", who: "scientist and President of India", means: "Hard times are what make success feel sweet.", src: "Wings of Fire (1999)" },
    { q: "To succeed in your mission, you must have single-minded devotion to your goal.", by: "A. P. J. Abdul Kalam", who: "scientist and President of India", means: "You reach a big goal only by giving it your complete focus.", src: "Wings of Fire (1999)" },
    { q: "Nothing worthwhile is ever achieved without deep thought and hard work.", by: "J. R. D. Tata", who: "Indian industrialist and aviation pioneer", means: "Anything of real value needs both careful thinking and steady effort.", src: "Letter to a schoolteacher on his guiding principles, 1965" },
    { q: "Freedom and power bring responsibility.", by: "Jawaharlal Nehru", who: "India’s first Prime Minister", means: "The more freedom and power you have, the more you must answer for how you use them.", src: "“Tryst with Destiny” speech, 14 August 1947" },
    { q: "Slowly, slowly, O mind, everything happens at its own pace. The gardener may water with a hundred pots, but the fruit comes only in its season.", by: "Kabir", who: "15th-century Indian poet-saint", means: "Be patient; some results cannot be hurried, however hard you push.", src: "Doha “Dheere dheere re mana”, in English translation" },
    { q: "You have a right to perform your prescribed duties, but you are not entitled to the fruits of your actions.", by: "Bhagavad Gita", who: "ancient Indian scripture", means: "Put your full effort into your work, and do not be tied to the reward.", src: "Chapter 2, verse 47 (translation by Swami Mukundananda)" },
    { q: "Elevate yourself through the power of your mind, and not degrade yourself, for the mind can be the friend and also the enemy of the self.", by: "Bhagavad Gita", who: "ancient Indian scripture", means: "Your own mind can lift you up or pull you down, so train it to help you.", src: "Chapter 6, verse 5 (translation by Swami Mukundananda)" },
    { q: "The deeper a sand well is dug, the more freely its water flows. Even so, the deeper a man’s learning, the greater is his wisdom.", by: "Tirukkural", who: "classic Tamil text by Thiruvalluvar", means: "The more deeply you study, the more wisdom you gain.", src: "Kural 396 (Himalayan Academy translation)" },
    { q: "When pleasant words are easy, bitter words to use, is, leaving sweet ripe fruit, the sour unripe to choose.", by: "Tirukkural", who: "classic Tamil text by Thiruvalluvar", means: "Speaking harshly when kind words are available is like picking sour fruit when ripe fruit is at hand.", src: "Kural 100 (translation by G. U. Pope)" },
    { q: "Truth alone triumphs, not falsehood.", by: "Mundaka Upanishad", who: "ancient Indian scripture", means: "In the end, truth wins and lies fail.", src: "Mundaka Upanishad 3.1.6; the source of India’s national motto, “Satyameva Jayate”" },
    { q: "Lead me from the unreal to the real. Lead me from darkness to light. Lead me from death to immortality.", by: "Brihadaranyaka Upanishad", who: "ancient Indian scripture", means: "A prayer to move from what is false to what is true, and from ignorance to knowledge.", src: "Brihadaranyaka Upanishad 1.3.28" },
    { q: "Hatred is never appeased by hatred in this world. By non-hatred alone is hatred appeased. This is a law eternal.", by: "Dhammapada", who: "collection of the Buddha’s sayings", means: "Hate cannot end hate; only goodwill can.", src: "Verse 5 (translation by Acharya Buddharakkhita)" },
    { q: "Better than a thousand useless words is one useful word, hearing which one attains peace.", by: "Dhammapada", who: "collection of the Buddha’s sayings", means: "One helpful word is worth more than a long speech that helps nobody.", src: "Verse 100 (translation by Acharya Buddharakkhita)" },
    { q: "Though one may conquer a thousand times a thousand men in battle, yet he indeed is the noblest victor who conquers himself.", by: "Dhammapada", who: "collection of the Buddha’s sayings", means: "The greatest victory is gaining control over yourself.", src: "Verse 103 (translation by Acharya Buddharakkhita)" },
    { q: "If it is not right, do not do it: if it is not true, do not say it.", by: "Marcus Aurelius", who: "Roman emperor and Stoic philosopher", means: "Do only what is right and say only what is true.", src: "Meditations, Book 12 (translation by George Long)" },
    { q: "The best way of avenging thyself is not to become like the wrong doer.", by: "Marcus Aurelius", who: "Roman emperor and Stoic philosopher", means: "The best answer to someone who wrongs you is to not become like them.", src: "Meditations, Book 6 (translation by George Long)" },
    { q: "No longer talk at all about the kind of man that a good man ought to be, but be such.", by: "Marcus Aurelius", who: "Roman emperor and Stoic philosopher", means: "Stop discussing what a good person is, and simply be one.", src: "Meditations, Book 10 (translation by George Long)" },
    { q: "We suffer more often in imagination than in reality.", by: "Seneca", who: "Roman Stoic philosopher and writer", means: "Most of our worries are about things that never actually happen.", src: "Letters to Lucilius, Letter 13 (translation by R. M. Gummere)" },
    { q: "While we are postponing, life speeds by.", by: "Seneca", who: "Roman Stoic philosopher and writer", means: "Every time we delay, we lose a part of our life that will not come back.", src: "Letters to Lucilius, Letter 1 (translation by R. M. Gummere)" },
    { q: "It is not that we have a short time to live, but that we waste a lot of it.", by: "Seneca", who: "Roman Stoic philosopher and writer", means: "Life is long enough if we use our time well.", src: "On the Shortness of Life (translation by C. D. N. Costa)" },
    { q: "Men are disturbed, not by things, but by the principles and notions which they form concerning things.", by: "Epictetus", who: "Greek Stoic philosopher, once a slave", means: "It is not events that upset us, but the way we think about them.", src: "Enchiridion, section 5 (translation by Elizabeth Carter)" },
    { q: "The unexamined life is not worth living.", by: "Socrates", who: "ancient Greek philosopher", means: "A good life needs us to stop and think about how we are living.", src: "Plato, Apology, 38a" },
    { q: "It is the mark of an educated man to look for precision in each class of things just so far as the nature of the subject admits.", by: "Aristotle", who: "ancient Greek philosopher", means: "A wise person expects only as much exactness as a subject can give.", src: "Nicomachean Ethics, Book 1 (translation by W. D. Ross)" },
    { q: "One swallow does not make a summer, nor does one day; and so too one day, or a short time, does not make a man blessed and happy.", by: "Aristotle", who: "ancient Greek philosopher", means: "One good day does not make a good life; goodness has to be kept up over time.", src: "Nicomachean Ethics, Book 1 (translation by W. D. Ross)" },
    { q: "To see what is right and not to do it is want of courage.", by: "Confucius", who: "ancient Chinese teacher and philosopher", means: "If you know the right thing and still do not do it, you are lacking courage.", src: "Analects 2.24 (translation by James Legge)" },
    { q: "When you know a thing, to hold that you know it; and when you do not know a thing, to allow that you do not know it; this is knowledge.", by: "Confucius", who: "ancient Chinese teacher and philosopher", means: "Real knowledge includes being honest about what you do not know.", src: "Analects 2.17 (translation by James Legge)" },
    { q: "Learning without thought is labour lost; thought without learning is perilous.", by: "Confucius", who: "ancient Chinese teacher and philosopher", means: "Study is wasted if you do not think about it, and thinking without study is risky.", src: "Analects 2.15 (translation by James Legge)" },
    { q: "A journey of a thousand miles begins with a single step.", by: "Lao Tzu", who: "ancient Chinese philosopher", means: "Every big task starts with one small action.", src: "Tao Te Ching, chapter 64" },
    { q: "Well done is better than well said.", by: "Benjamin Franklin", who: "American statesman, scientist and writer", means: "Doing good work matters more than talking about it.", src: "Poor Richard’s Almanack, 1737" },
    { q: "Lost time is never found again.", by: "Benjamin Franklin", who: "American statesman, scientist and writer", means: "Time that is wasted can never be got back.", src: "Poor Richard’s Almanack, 1748" },
    { q: "Beware of little expenses; a small leak will sink a great ship.", by: "Benjamin Franklin", who: "American statesman, scientist and writer", means: "Small, careless spending can slowly destroy even a large fortune.", src: "The Way to Wealth, 1758" },
    { q: "Always bear in mind that your own resolution to succeed, is more important than any other one thing.", by: "Abraham Lincoln", who: "16th President of the United States", means: "Your own firm decision to succeed matters more than anything else.", src: "Letter to Isham Reavis, 5 November 1855" },
    { q: "Ignorance more frequently begets confidence than does knowledge.", by: "Charles Darwin", who: "English naturalist, explained evolution", means: "People who know little are often more sure of themselves than people who know a lot.", src: "The Descent of Man (1871), Introduction" },
    { q: "A man who dares to waste one hour of time has not discovered the value of life.", by: "Charles Darwin", who: "English naturalist, explained evolution", means: "Anyone who understands how precious life is will not waste even an hour.", src: "Letter to his sister Susan Darwin, 4 August 1836" },
    { q: "One never notices what has been done; one can only see what remains to be done.", by: "Marie Curie", who: "physicist, twice a Nobel laureate", means: "She always looked at the work still ahead, not at what was already finished.", src: "Letter to her brother, 1894" },
    { q: "Life is not easy for any of us. But what of that? We must have perseverance and above all confidence in ourselves.", by: "Marie Curie", who: "physicist, twice a Nobel laureate", means: "Life is hard for everyone, so we must keep going and believe in ourselves.", src: "Quoted in Madame Curie (1937), the biography by her daughter Eve Curie" },
    { q: "The first principle is that you must not fool yourself, and you are the easiest person to fool.", by: "Richard Feynman", who: "American physicist and Nobel laureate", means: "Be most careful about the lies you tell yourself, because they are the easiest to believe.", src: "“Cargo Cult Science”, Caltech commencement address, 1974" },
    { q: "For a successful technology, reality must take precedence over public relations, for Nature cannot be fooled.", by: "Richard Feynman", who: "American physicist and Nobel laureate", means: "Facts matter more than image; you cannot talk your way around how the world really works.", src: "Appendix to the report on the Challenger space shuttle accident, 1986" },
    { q: "Nothing in life is as important as you think it is, while you are thinking about it.", by: "Daniel Kahneman", who: "psychologist and Nobel laureate in economics", means: "Whatever you are focusing on right now seems bigger than it really is.", src: "Thinking, Fast and Slow (2011)" },
    { q: "There is surely nothing quite so useless as doing with great efficiency what should not be done at all.", by: "Peter Drucker", who: "Austrian-American management thinker and writer", means: "Doing the wrong task very well is still a waste; first choose the right task.", src: "“Managing for Business Effectiveness”, Harvard Business Review, 1963" },
    { q: "I learned that courage was not the absence of fear, but the triumph over it.", by: "Nelson Mandela", who: "South African freedom leader and President", means: "Being brave does not mean having no fear; it means acting in spite of fear.", src: "Long Walk to Freedom (1994)" },
    { q: "After climbing a great hill, one only finds that there are many more hills to climb.", by: "Nelson Mandela", who: "South African freedom leader and President", means: "Reaching one goal shows you the next ones; the work of life never fully ends.", src: "Long Walk to Freedom (1994)" },
    { q: "Education is the most powerful weapon which you can use to change the world.", by: "Nelson Mandela", who: "South African freedom leader and President", means: "Learning is the strongest tool anyone has for making the world better.", src: "Speech at the launch of Mindset Network, Johannesburg, 16 July 2003" },
    { q: "The time is always right to do what is right.", by: "Martin Luther King Jr.", who: "American civil rights leader", means: "There is never a wrong moment to do the right thing.", src: "Address at Oberlin College, 1964" },
    { q: "Darkness cannot drive out darkness; only light can do that. Hate cannot drive out hate; only love can do that.", by: "Martin Luther King Jr.", who: "American civil rights leader", means: "You cannot end hatred with more hatred; only kindness can end it.", src: "Strength to Love (1963)" },
    { q: "Intelligence plus character: that is the goal of true education.", by: "Martin Luther King Jr.", who: "American civil rights leader", means: "Real education should make a person both clever and good.", src: "“The Purpose of Education”, Morehouse College student paper, 1947" },
    { q: "Although the world is full of suffering, it is full also of the overcoming of it.", by: "Helen Keller", who: "deaf-blind American author and activist", means: "There is much pain in the world, but also many people who rise above it.", src: "Optimism (1903)" },
    { q: "Life is either a daring adventure, or nothing.", by: "Helen Keller", who: "deaf-blind American author and activist", means: "Life is worth living only if we are willing to take chances.", src: "The Open Door (1957)" },
    { q: "You may not control all the events that happen to you, but you can decide not to be reduced by them.", by: "Maya Angelou", who: "American poet and memoirist", means: "You cannot choose everything that happens, but you can refuse to let it make you smaller.", src: "Letter to My Daughter (2008)" },
    { q: "When we are no longer able to change a situation, we are challenged to change ourselves.", by: "Viktor Frankl", who: "psychiatrist and Holocaust survivor", means: "When you cannot change what is happening, you can still change how you face it.", src: "Man’s Search for Meaning" },
    { q: "It is not from the benevolence of the butcher, the brewer, or the baker, that we expect our dinner, but from their regard to their own interest.", by: "Adam Smith", who: "Scottish economist and philosopher", means: "People provide goods and services mainly to earn a living, and that is how trade serves everyone.", src: "The Wealth of Nations (1776), Book 1, Chapter 2" },
    { q: "If I have seen further it is by standing on the shoulders of Giants.", by: "Isaac Newton", who: "English physicist and mathematician", means: "His discoveries were possible only because of the work of great thinkers before him.", src: "Letter to Robert Hooke, 1675" },
    { q: "The important thing is not to stop questioning. Curiosity has its own reason for existing.", by: "Albert Einstein", who: "physicist who developed relativity", means: "Never stop asking questions; curiosity is valuable in itself.", src: "Interview in LIFE magazine, 2 May 1955" },
    { q: "I have no special talents. I am only passionately curious.", by: "Albert Einstein", who: "physicist who developed relativity", means: "He believed his success came from deep curiosity, not from special gifts.", src: "Letter to Carl Seelig, 11 March 1952" },
    { q: "Never use a long word where a short one will do.", by: "George Orwell", who: "English novelist and essayist", means: "Choose simple words when they say the same thing.", src: "“Politics and the English Language”, 1946" },
    { q: "I have made this letter longer than usual, only because I have not had the time to make it shorter.", by: "Blaise Pascal", who: "French mathematician and philosopher", means: "Writing briefly and clearly takes more time and effort than writing at length.", src: "Provincial Letters, Letter 16, 1657" }
  ]
};
